using System.Runtime.Versioning;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Win32;

namespace InventoryManagement.Licensing;

/// <summary>
/// Computes the ID a license is bound to. It is a hash of values that stay
/// the same for the life of a Windows installation on one PC, but differ
/// between PCs:
///
/// - MachineGuid: generated by Windows at install time, unique per install.
/// - The board/system manufacturer and model reported by the BIOS.
///
/// Reinstalling Windows or moving to a new PC produces a new ID, so the
/// customer needs a replacement license from the vendor in that case (their
/// backups still restore - see <see cref="LicenseData.BackupKey"/>).
///
/// The ID is shown to the customer as 25 base32 characters in groups of
/// five, so it is easy to read out or paste into an email.
/// </summary>
public static class MachineIdentity
{
    private const string Alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

    [SupportedOSPlatform("windows")]
    public static string GetCurrentMachineId() => FromComponents(ReadComponents());

    /// <summary>Exposed separately so the hashing/formatting can be tested without the real registry.</summary>
    public static string FromComponents(IEnumerable<string> components)
    {
        var joined = string.Join("|", components.Select(c => c.Trim().ToUpperInvariant()));
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes("InventoryManagement.MachineId.v1|" + joined));

        var builder = new StringBuilder();
        var bitBuffer = 0;
        var bitCount = 0;
        foreach (var b in hash)
        {
            bitBuffer = (bitBuffer << 8) | b;
            bitCount += 8;
            while (bitCount >= 5 && builder.Length < 25)
            {
                bitCount -= 5;
                builder.Append(Alphabet[(bitBuffer >> bitCount) & 31]);
            }
        }

        return Format(builder.ToString());
    }

    /// <summary>
    /// Checks a machine ID typed or pasted by a person (any case, with or
    /// without dashes) and returns it in the canonical XXXXX-XXXXX-... form.
    /// </summary>
    public static bool TryParse(string input, out string machineId)
    {
        var normalized = Normalize(input);
        if (normalized.Length != 25 || normalized.Any(c => !Alphabet.Contains(c)))
        {
            machineId = string.Empty;
            return false;
        }

        machineId = Format(normalized);
        return true;
    }

    private static string Format(string normalized) =>
        string.Join("-", Enumerable.Range(0, 5).Select(i => normalized.Substring(i * 5, 5)));

    /// <summary>Upper-cases and strips separators/whitespace, so "abcde-fghij" and "ABCDEFGHIJ" compare equal.</summary>
    public static string Normalize(string machineId) =>
        new(machineId.Where(char.IsLetterOrDigit).Select(char.ToUpperInvariant).ToArray());

    public static bool AreEqual(string a, string b) =>
        string.Equals(Normalize(a), Normalize(b), StringComparison.Ordinal);

    [SupportedOSPlatform("windows")]
    private static IEnumerable<string> ReadComponents()
    {
        // Registry64 explicitly: MachineGuid lives only in the 64-bit view,
        // and a 32-bit process would otherwise be redirected to WOW6432Node,
        // where it does not exist.
        using var localMachine = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64);

        using (var cryptography = localMachine.OpenSubKey(@"SOFTWARE\Microsoft\Cryptography"))
        {
            var machineGuid = cryptography?.GetValue("MachineGuid") as string;
            if (string.IsNullOrWhiteSpace(machineGuid))
            {
                throw new InvalidOperationException("Could not read this PC's Windows machine identifier.");
            }

            yield return machineGuid;
        }

        using var bios = localMachine.OpenSubKey(@"HARDWARE\DESCRIPTION\System\BIOS");
        foreach (var valueName in new[] { "SystemManufacturer", "SystemProductName", "BaseBoardManufacturer", "BaseBoardProduct" })
        {
            yield return bios?.GetValue(valueName) as string ?? string.Empty;
        }
    }
}
